namespace Superiorly.PostInstall.Services;

public static partial class TranslationService
{
    private static readonly Dictionary<string, string> ActionInfo_vi = new()
    {

            ["process-explorer"]="Trình quản lý tác vụ nâng cao hiện mức dùng handle/DLL theo thời gian thực, cây tiến trình, bộ nhớ GPU và xác minh ký mã. Phân giải ký hiệu ngăn xếp luồng và hiện I/O theo tiến trình. Công cụ chẩn đoán chỉ đọc.",
            ["nsudo"]="Chạy tiến trình với quyền TrustedInstaller, SYSTEM hoặc đầy đủ đặc quyền. Thiết yếu để sửa tệp được bảo vệ hoặc chiếm quyền tài nguyên bị khóa. Cảnh báo: bỏ qua mọi kiểm tra bảo mật.",
            ["driverview"]="Liệt kê mọi trình điều khiển chế độ nhân với phiên bản, loại và mức dùng bộ nhớ. Xác định trình điều khiển chưa ký hoặc lỗi thời có thể gây BSOD. Hữu ích để chẩn đoán xung đột trình điều khiển.",
            ["cru"]="Thêm độ phân giải, tần số quét và tham số thời gian tùy chỉnh qua ghi đè EDID trong sổ đăng ký. Khởi động lại trình điều khiển để áp dụng mà không cần khởi động lại máy. Cảnh báo: giá trị sai có thể gây mất tín hiệu.",
            ["windows-update-manager"]="Điều khiển chi tiết Windows Update: ẩn/hiện từng bản cập nhật, hoãn cập nhật chất lượng, quản lý cập nhật trình điều khiển và tạm dừng mọi cập nhật. Tránh bản cập nhật lỗi mà vẫn giữ bản vá bảo mật.",
            ["mousetester"]="Phân tích tính nhất quán tốc độ lấy mẫu chuột, độ ổn định đầu vào và hiệu năng cảm biến. Ghi dữ liệu chuyển động thô và vẽ vận tốc, jitter và angle snapping. Chế độ hai thiết bị đo độ trễ đầu vào giữa hai chuột.",
            ["geek-uninstaller"]="Trình gỡ cài đặt portable cho chương trình cứng đầu, ứng dụng Windows Store và tiện ích trình duyệt. Quét sổ đăng ký và hệ tệp để tìm mục còn sót sau khi gỡ. Không cần cài đặt.",
            ["measuresleep"]="Đo độ chính xác Sleep() của Windows bằng cách so sánh khoảng thực tế với yêu cầu. Xác định sự cố độ phân giải bộ định thời gây micro-stutter và trễ đầu vào. Kết hợp với SetTimerResolution để xác minh cải thiện.",
            ["ocat"]="Lớp phủ FPS và chụp thời gian khung hình cho D3D11, D3D12 và Vulkan. Dùng Intel PresentMon để đo thời gian chính xác. Ghi dấu thời gian khung hình bằng phím nóng. Hoạt động với mọi hãng GPU.",
            ["onboard-memory-manager"]="Cấu hình DPI, gán nút và đèn trên bộ nhớ trong của chuột Logitech G. Loại bỏ nhu cầu chạy G HUB nền. Hỗ trợ Pro X Superlight, G Pro, G502, G305 và dòng G khác.",
            ["performance-measurement"]="Nâng ngắt đồng hồ Windows lên 0.5ms qua NtSetTimerResolution, giảm trễ đầu vào và cải thiện nhịp khung hình. Đóng ứng dụng để khôi phục bộ định thời mặc định. Thiết yếu cho game thi đấu và sản xuất âm thanh.",
            ["autoruns"]="Hiện mọi chương trình, dịch vụ, trình điều khiển và tác vụ theo lịch tự khởi động. An toàn khi tắt mục không mong muốn đã biết. Dùng Ẩn mục Microsoft để tập trung vào bên thứ ba. Rủi ro: tắt Winlogon/dịch vụ có thể khiến máy không khởi động.",
            ["devicecleanup"]="Xóa mục sổ đăng ký cho phần cứng đã ngắt kết nối. Chỉ an toàn cho thiết bị vắng mặt. Tương tự Microsoft DevNodeClean. Rủi ro: tối thiểu.",
            ["gointerruptpolicy"]="Đặt ái lực CPU và chính sách ưu tiên cho tiến trình. Hữu ích để ghim engine game vào lõi cụ thể. Rủi ro: ái lực sai có thể giảm hiệu năng.",
            ["serviwin"]="Liệt kê dịch vụ và trình điều khiển Windows với trạng thái. An toàn khi dừng/tắt dịch vụ không cần thiết đã biết. Rủi ro: tắt dịch vụ quan trọng (RPC, DCOM) làm hỏng hệ thống.",
            ["usbtreeview"]="Hiện cây thiết bị USB với trạng thái nguồn và băng thông. Hữu ích để gỡ lỗi USB. Chỉ đọc.",
            ["ddu"]="Xóa mọi tàn dư trình điều khiển GPU (tệp, sổ đăng ký, thư mục) mà trình gỡ chuẩn bỏ sót. Dùng khi đổi hãng GPU hoặc sửa trình điều khiển hỏng. Chạy ở Chế độ an toàn để có kết quả tốt nhất.",
            ["filterkeysetter"]="Điều chỉnh giá trị FilterKeys của Windows vượt giới hạn Bảng điều khiển: độ trễ lặp, tốc độ lặp, độ trễ chấp nhận và thời gian nảy. Ảnh hưởng trình soạn thảo văn bản và ứng dụng dùng đầu vào bàn phím cấp cao. Game hiện đại dùng DirectInput hoặc Raw Input không bị ảnh hưởng.",
            ["brave-debloat"]="Tắt tính năng phụ và đo lường từ xa của Brave. Khởi động lại Brave; hiện là được quản lý.",
            ["edge-debloat"]="Tắt mua sắm, tiện ích thanh bên và đo lường từ xa. Khởi động lại Edge; hiện là được quản lý.",
            ["throttlestop"]="Giảm điện áp CPU qua FIVR, điều khiển turbo boost (PL1/PL2), bật/tắt BD PROCHOT và quản lý Speed Shift/EPP. Giảm nhiệt độ và ngăn giảm xung do nhiệt. Yêu cầu quyền quản trị.",
            ["radeonsoftwareslimmer"]="Loại bỏ thành phần không cần thiết của AMD Radeon Software (đo lường từ xa, tiến trình nền, bloatware). Giảm RAM 200-400MB. An toàn cho mọi GPU AMD.",
            ["moreclocktool"]="Điều khiển chi tiết xung nhịp GPU AMD, đường cong điện áp và trạng thái nguồn. Thiết yếu cho Polaris, Vega và RDNA1. Cảnh báo: điện áp sai có thể gây mất ổn định GPU.",
            ["morepowertool"]="Sửa đổi bảng nguồn GPU AMD để ghi đè giới hạn công suất, đường cong quạt và giới hạn nhiệt ở cấp trình điều khiển. Hỗ trợ Polaris, Vega, RDNA1/2/3. Cảnh báo: có thể làm hỏng phần cứng vĩnh viễn.",
            ["radeonmod"]="Chỉnh sửa giá trị sổ đăng ký ẩn của trình điều khiển AMD: Flip Queue Size, bộ nhớ đệm shader, ULPS, bộ đệm ba, tessellation. Hỗ trợ Radeon HD 5000 đến RX 500. Luôn sao lưu sổ đăng ký trước.",
            ["nvcleanstall"]="Rút gọn trình điều khiển NVIDIA chỉ còn phần thiết yếu. Loại bỏ đo lường từ xa, GeForce Experience, âm thanh HDMI. Giảm hơn 500MB ổ đĩa và loại bỏ dịch vụ nền. Chỉ cài trình điều khiển hiển thị lõi và PhysX.",
            ["nvidia-inspector"]="Giám sát GPU theo thời gian thực: tốc độ xung, điện áp, nhiệt độ, tốc độ quạt, công suất. Đọc cảm biến ở cấp phần cứng. Hữu ích để xác minh ép xung ổn định và theo dõi giảm xung do nhiệt.",
            ["apply-nip"]="Ghi đè hồ sơ trình điều khiển cấu hình sẵn cho từng game. Tối ưu AA, AF, chất lượng texture và cài đặt nguồn theo từng tựa game. Hồ sơ phụ thuộc phiên bản trình điều khiển NVIDIA.",
            ["force-pstate0"]="Khóa GPU NVIDIA ở trạng thái hiệu năng tối đa (P0), ngăn chia tỷ lệ xung gây dao động thời gian khung hình. Cảnh báo: tăng công suất chờ 20-40W và nhiệt độ. Tắt khi không chơi game.",
            ["lazymodetimeout"]="Thời gian chờ chu kỳ lười phát hiện chờ MMCSS. Mặc định: 1.000.000 (100ms). Thấp hơn = đánh thức nhanh hơn nhưng nhiều lần đánh thức CPU hơn. Cài đặt ẩn không có tài liệu.",
            ["systemresponsiveness"]="Dự trữ MMCSS cho tác vụ nền (0-100, mặc định=20). Giá trị 0-9 bị kẹp thành 20. 10-100 làm tròn xuống bội số 10 gần nhất. 100 tắt MMCSS.",
            ["receive-buffers"]="Kích thước bộ đệm nhận của card mạng. Cao hơn có thể cải thiện thông lượng. Rủi ro: tốn bộ nhớ hơn.",
            ["transmit-buffers"]="Kích thước bộ đệm gửi của card mạng. Cao hơn có thể cải thiện thông lượng. Rủi ro: tốn bộ nhớ hơn.",
            ["csrss-priority"]="Ưu tiên Client/Server Runtime. Sửa đổi có thể ảnh hưởng khả năng phản hồi. Rủi ro: giá trị sai có thể gây trễ giao diện.",
            ["iolatencycap"]="Giới hạn độ trễ I/O tính bằng ms. Thấp hơn = I/O phản hồi nhanh hơn. Rủi ro: quá thấp có thể gây lỗi I/O.",
            ["iopagelocklimit"]="Giới hạn khóa trang I/O tính bằng byte. Điều khiển bộ nhớ khóa cho I/O. Rủi ro: giá trị sai có thể gây mất ổn định.",
            ["nagle-algorithm"]="Thuật toán Nagle gộp gói TCP nhỏ. Tắt giúp giảm độ trễ cho ứng dụng thời gian thực. Rủi ro: có thể tăng chi phí mạng.",
            ["nolazymode"]="Tắt chế độ lười phát hiện chờ MMCSS. Luồng giữ ở mức ưu tiên tăng cường. Có thể tăng điện năng CPU. Cài đặt ẩn không có tài liệu.",
            ["tsc-sync-policy"]="Chính sách đồng bộ TSC trên các lõi. Rủi ro: có thể ảnh hưởng ứng dụng nhạy thời gian.",
            ["useplatformtick"]="Ép dùng tick nền tảng thay vì HPET. Có thể giảm độ trễ bộ định thời. Rủi ro: một số phần cứng có thể không hỗ trợ.",
            ["disable-mpo"]="Tắt Multi-Plane Overlay. Có thể sửa giật hình ở một số game. Rủi ro: có thể tăng mức dùng GPU ở chế độ cửa sổ.",
            ["disable-interrupt-steering"]="Tắt điều hướng ngắt. Ngắt ở lại trên lõi đầu tiên. Rủi ro: có thể tăng độ trễ lõi đầu tiên.",
            ["disable-power-throttling"]="Tắt giới hạn điện của Windows. Đảm bảo xung CPU ổn định. Rủi ro: tăng tiêu thụ điện trên laptop.",
            ["threaded-dpc"]="Bật xử lý DPC đa luồng. Có thể giảm đỉnh trễ DPC. Rủi ro: tối thiểu trên phần cứng hiện đại.",
            ["cpu-idle"]="Điều khiển trạng thái chờ CPU (C-state). Thấp hơn = ngủ sâu hơn (tiết kiệm điện). Cao hơn = CPU sẵn sàng (độ trễ thấp hơn).",
            ["force-direct-flip"]="Ép Direct Flip cho toàn màn hình. Bỏ qua DWM. Rủi ro: có thể ảnh hưởng phần mềm quay màn hình.",
            ["force-independent-flip"]="Ép independent flip cho toàn màn hình. Giảm chi phí DWM. Rủi ro: sự cố đa màn hình.",
            ["force-flip-true-immediate"]="Ép thời gian flip tức thì. Giảm độ trễ khung hình. Rủi ro: có thể gây xé hình.",
            ["disablepagingexecutive"]="Giữ trình điều khiển nhân trong RAM. Giảm I/O ổ đĩa. Rủi ro: tốn RAM hơn.",
            ["disablepagecombining"]="Tắt gộp trang (khử trùng lặp bộ nhớ). Rủi ro: tăng nhẹ mức dùng bộ nhớ.",
